  LinkObj   = pci.PCI_EXPRESS_EXTENDED_CAPABILITIES_LINK_DECLARATION.from_buffer (PciRaw, ExtCapPtr)
  LinkCount = max ((LinkObj.ElementSelfDescription >> 8) & 0xFF, 1)
