def PcieExtCapGetAerStruct (ExtCapId, PciRaw, ExtCapPtr):
  AerObj = EFIPY_PCIE_EXT_CAPABILITY_AER_ENDPOINT.from_buffer (PciRaw, ExtCapPtr)
  HasTlpPrefix = bool (AerObj.AdvancedErrorCapabilitiesAndControl.Bits.TlpPrefixLogPresent)

  PortType = 0
  if PciRaw[pci.PCI_PRIMARY_STATUS_OFFSET] & pci.EFI_PCI_STATUS_CAPABILITY:
    for CapPtr, CapId, _ in BuildPciCapabilitiesList (PciRaw, GetPciCapabilityPointer (PciRaw)):
      if CapId == pci.EFI_PCI_CAPABILITY_ID_PCIEXP:
        PortType = ((PciRaw[CapPtr + 2] | (PciRaw[CapPtr + 3] << 8)) >> 4) & 0x0F
        break

  if PortType in (4, 10):
    return EFIPY_PCIE_EXT_CAPABILITY_AER_ROOT_TLP if HasTlpPrefix else EFIPY_PCIE_EXT_CAPABILITY_AER_ROOT
  elif PortType in (7, 8):
    return EFIPY_PCIE_EXT_CAPABILITY_AER_BRIDGE
  else:
    return EFIPY_PCIE_EXT_CAPABILITY_AER_ENDPOINT_TLP if HasTlpPrefix else EFIPY_PCIE_EXT_CAPABILITY_AER_ENDPOINT

